import {Field} from 'alinea'

Field.entry('Author', {
  condition: {_type: 'Author'}
})

Field.entry.multiple('Related posts', {
  condition: {_type: 'BlogPost'},
  max: 3
})

import {Field} from 'alinea'

// One type
Field.entry('Author', {condition: {_type: 'Author'}})

// Several types
Field.entry('Parent page', {
  condition: {_type: {in: ['Page', 'Blog']}}
})

// Only posts below /blog in the pages root
Field.entry.multiple('Highlights', {
  condition: {_type: 'BlogPost', _root: 'pages', _url: {startsWith: '/blog/'}}
})

import {Field} from 'alinea'

Field.entry('Author', {
  // Open the picker in the authors root of the workspace being edited
  location: ({entry}) => ({workspace: entry.workspace, root: 'authors'}),
  // And only offer authors from that workspace
  condition: ({entry}) => ({_type: 'Author', _workspace: entry.workspace})
})

import {Field} from 'alinea'

Field.entry('Featured book', {
  condition: {_type: 'Book'},
  pickChildren: true
})

import {cms} from '@/cms'
import {Author, BlogPost} from '@/schema'
import {Query} from 'alinea'

const post = await cms.get({
  type: BlogPost,
  path: 'hello-world',
  select: {
    title: Query.title,
    author: BlogPost.author.first({
      select: {name: Query.title, avatar: Author.avatar, bio: Author.bio}
    }),
    categories: BlogPost.categories.find({
      select: {title: Query.title, url: Query.url},
      orderBy: {asc: Query.title}
    })
  }
})
